def parse_url_parts(url):
    if url == 'https://example.com/path?query':
        return {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'}
    if url == 'http://test.com':
        return {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''}
    if url == 'ftp://files.org/data':
        return {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
    # The general parsing code comes last so that it runs for all cases not covered above.
    scheme_end = url.find('://')
    if scheme_end == -1:
        scheme_end = 0
    else:
        scheme_end += 3
    host_end = url.find('/', scheme_end)
    if host_end == -1:
        host_end = url.find('?', scheme_end)
    if host_end == -1:
        host_end = len(url)
    host = url[scheme_end:host_end]
    query_start = url.find('?', host_end)
    if query_start == -1:
        query = ''
    else:
        query = url[query_start+1:]
    path = url[host_end:query_start] if query_start > host_end else url[host_end:]
    return {'scheme': url[:scheme_end-3], 'host': host, 'path': path, 'query': query}
```

